-- Create "resource_artifacts" table
CREATE TABLE `resource_artifacts` (`id` varchar(32) NOT NULL, `created_at` datetime(6) NOT NULL, `team_id` varchar(32) NOT NULL, `author_id` varchar(32) NOT NULL, `package` varchar(214) NOT NULL, `version` varchar(100) NOT NULL, `sha256` varchar(64) NOT NULL, `size` bigint NOT NULL, `files` json NOT NULL, `published` bool NOT NULL DEFAULT 0, PRIMARY KEY (`id`), INDEX `resourceartifact_team_id_author_id` (`team_id`, `author_id`), UNIQUE INDEX `resourceartifact_team_id_package_version` (`team_id`, `package`, `version`)) CHARSET utf8mb4 COLLATE utf8mb4_bin;
